var l=[{title:`Два поширені застосування`,text:`RPE заняття оцінює загальну складність усього тренування, часто за шкалою у стилі категорій і співвідношень від 0 до 10, що йде від спокою до максимального зусилля. RPE підходу оцінює один підхід силового тренування. Вони вимірюють різне: один підхід може бути надзвичайно важким у занятті, яке загалом здавалося помірним.`},{title:`RPE підходу та повторення в запасі`,text:`Одна система силового тренування пов’язує кожну оцінку з кількістю повторень, які, на вашу думку, лишалися. RPE 10 означає, що ви не могли б зробити ще одне повне повторення із задуманою технікою, RPE 9 означає, що лишалося одне, а RPE 8 означає, що лишалося приблизно два. Це оцінки, а не точні фізіологічні виміри, і з тренувальним досвідом ви стаєте в них кращими.`},{title:`Приклади`,text:`Швидка 25-хвилинна прогулянка може здаватися одній людині на 4/10, а розтренованому початківцю на 7/10. Підхід із восьми присідів, де можливі ще приблизно два повторення, був би приблизно RPE 8 за шкалою повторень у запасі для підйомів. Завжди вказуйте, якою шкалою ви користуєтеся, інакше числа плутатимуть.`},{title:`Типові помилки`,text:`Оцінки втрачають цінність, якщо ви оцінюєте зусилля лише за тим, наскільки спітніли, плутаєте м’язову болючість зі складністю заняття або завжди обираєте 10, бо тренування «має бути важким». Сон, стрес, спека та незвичні рухи змінюють те, наскільки важкою здається вправа, тож читайте кожну оцінку в її контексті.`},{title:`Перетворення оцінок на рішення`,text:`Якщо кілька занять здаються набагато важчими за заплановане, подивіться на сон, навантаження, кількість підходів, відпочинок і відновлення. Якщо заняття постійно здаються дуже легкими, а ваша техніка надійна, спробуйте невелике збільшення наступного разу. Однієї незвичної оцінки недостатньо, щоб діагностувати перетренованість чи робити великі зміни.`},{title:`Як це працює в TrainUp`,text:`Після кожного тренування ви оцінюєте все заняття від 1 до 10. Сприймайте це число як зусилля заняття і не перетворюйте його на RPE підходу чи повторення в запасі. Дивіться на свої оцінки поряд із тим, яку частину кожного тренування ви завершили, протягом кількох тренувань.`}];var i=[{label:`Зурдос та ін.: дослідження RPE на основі RIR`,url:`https://pubmed.ncbi.nlm.nih.gov/26049792/`},{label:`Гелмс та ін.: практичні поради щодо RPE`,url:`https://pubmed.ncbi.nlm.nih.gov/27531969/`},{label:`CDC: рекомендації щодо зусилля`,url:`https://www.cdc.gov/physical-activity-basics/measuring/`}];var R={sections:l,sources:i};export{R as default,l as sections,i as sources};